<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class LibraryOperationsController extends Controller{
 private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('librarian')||$r->user()->canDo('library.manage'),403);}
 public function readers(Request $r){$this->manage($r);$rows=DB::table('library_readers as lr')->leftJoin('students as s','s.id','=','lr.student_id')->leftJoin('teachers as t','t.id','=','lr.teacher_id')->select('lr.*','s.last_name as student_last','s.first_name as student_first','t.last_name as teacher_last','t.first_name as teacher_first')->orderByDesc('lr.id')->get();$students=DB::table('students')->where('status','active')->orderBy('last_name')->get();$teachers=DB::table('teachers')->where('active',1)->orderBy('last_name')->get();return view('library.readers',compact('rows','students','teachers'));}
 public function reader(Request $r){$this->manage($r);$d=$r->validate(['reader_type'=>'required|in:student,teacher','student_id'=>'nullable|exists:students,id','teacher_id'=>'nullable|exists:teachers,id']);$sid=$d['reader_type']==='student'?($d['student_id']??null):null;$tid=$d['reader_type']==='teacher'?($d['teacher_id']??null):null;abort_if(!$sid&&!$tid,422,'Выберите читателя.');$prefix=$sid?'S':'T';$id=$sid?:$tid;$card=$prefix.str_pad((string)$id,8,'0',STR_PAD_LEFT);DB::table('library_readers')->updateOrInsert($sid?['student_id'=>$sid]:['teacher_id'=>$tid],['card_number'=>$card,'barcode'=>'CHIST-'.$card,'active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back();}
 public function readerStatus(Request $r,$reader){$this->manage($r);$d=$r->validate(['active'=>'required|boolean']);abort_unless(DB::table('library_readers')->where('id',$reader)->exists(),404);DB::table('library_readers')->where('id',$reader)->update(['active'=>(bool)$d['active'],'updated_at'=>now()]);return back()->with('success','Статус читательского билета обновлён');}
 public function reserve(Request $r,$book){abort_unless($r->user()->student_id||$r->user()->teacher_id,403);$exists=DB::table('library_reservations')->where('library_book_id',$book)->where('status','waiting')->where($r->user()->student_id?'student_id':'teacher_id',$r->user()->student_id?:$r->user()->teacher_id)->exists();if(!$exists)DB::table('library_reservations')->insert(['library_book_id'=>$book,'student_id'=>$r->user()->student_id,'teacher_id'=>$r->user()->teacher_id,'status'=>'waiting','reserved_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Книга зарезервирована.');}
 public function operations(Request $r){$this->manage($r);$suppliers=DB::table('library_suppliers')->orderBy('name')->get();$receipts=DB::table('library_receipts as x')->leftJoin('library_suppliers as s','s.id','=','x.supplier_id')->select('x.*','s.name as supplier_name')->orderByDesc('received_on')->get();$reservations=DB::table('library_reservations as x')->join('library_books as b','b.id','=','x.library_book_id')->leftJoin('students as s','s.id','=','x.student_id')->leftJoin('teachers as t','t.id','=','x.teacher_id')->where('x.status','waiting')->select('x.*','b.title','s.last_name as student_last','t.last_name as teacher_last')->orderBy('x.reserved_at')->get();return view('library.operations',compact('suppliers','receipts','reservations'));}
 public function supplier(Request $r){$this->manage($r);$d=$r->validate(['name'=>'required|string|max:255','inn'=>'nullable|string|max:20','contact'=>'nullable|string|max:500']);DB::table('library_suppliers')->insert($d+['created_at'=>now(),'updated_at'=>now()]);return back();}
 public function supplierUpdate(Request $r,$supplier){$this->manage($r);abort_unless(DB::table('library_suppliers')->where('id',$supplier)->exists(),404);$d=$r->validate(['name'=>'required|string|max:255','inn'=>'nullable|string|max:20','contact'=>'nullable|string|max:500']);DB::table('library_suppliers')->where('id',$supplier)->update($d+['updated_at'=>now()]);return back()->with('success','Поставщик обновлён');}
 public function receipt(Request $r){$this->manage($r);$d=$r->validate(['supplier_id'=>'nullable|exists:library_suppliers,id','document_number'=>'nullable|string|max:100','received_on'=>'required|date','amount'=>'nullable|numeric|min:0']);DB::table('library_receipts')->insert($d+['created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
 public function receiptUpdate(Request $r,$receipt){$this->manage($r);abort_unless(DB::table('library_receipts')->where('id',$receipt)->exists(),404);$d=$r->validate(['supplier_id'=>'nullable|exists:library_suppliers,id','document_number'=>'nullable|string|max:100','received_on'=>'required|date','amount'=>'nullable|numeric|min:0']);DB::table('library_receipts')->where('id',$receipt)->update($d+['updated_at'=>now()]);return back()->with('success','Поступление обновлено');}
 public function reservationStatus(Request $r,$reservation){$this->manage($r);$d=$r->validate(['status'=>'required|in:waiting,ready,fulfilled,cancelled']);abort_unless(DB::table('library_reservations')->where('id',$reservation)->exists(),404);DB::table('library_reservations')->where('id',$reservation)->update(['status'=>$d['status'],'updated_at'=>now()]);return back()->with('success','Статус резерва обновлён');}
 public function writeoff(Request $r,$copy){$this->manage($r);$x=DB::table('library_copies')->find($copy);abort_if(!$x,404);abort_if($x->status==='loaned',422,'Сначала зарегистрируйте возврат экземпляра.');$d=$r->validate(['reason'=>'required|string|max:255','act_number'=>'required|string|max:100']);DB::table('library_copies')->where('id',$copy)->update(['status'=>'written_off','written_off_on'=>today(),'writeoff_reason'=>$d['reason'],'writeoff_act_number'=>$d['act_number'],'updated_at'=>now()]);return back()->with('success','Экземпляр списан без удаления истории.');}
 public function inventories(Request $r){$this->manage($r);$rows=DB::table('library_inventories')->orderByDesc('id')->get();return view('library.inventories',compact('rows'));}
 public function inventoryStart(Request $r){$this->manage($r);$d=$r->validate(['number'=>'nullable|string|max:100']);$id=DB::table('library_inventories')->insertGetId(['number'=>$d['number']??null,'started_on'=>today(),'status'=>'open','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return redirect()->route('library.inventory.show',$id);}
 public function inventoryShow(Request $r,$id){$this->manage($r);$inv=DB::table('library_inventories')->find($id);abort_if(!$inv,404);$total=DB::table('library_copies')->whereNotIn('status',['written_off','lost'])->count();$found=DB::table('library_inventory_scans')->where('library_inventory_id',$id)->count();$missing=DB::table('library_copies as c')->whereNotIn('c.status',['written_off','lost'])->whereNotExists(fn($q)=>$q->select(DB::raw(1))->from('library_inventory_scans as s')->where('s.library_inventory_id',$id)->whereColumn('s.library_copy_id','c.id'))->select('c.*')->limit(200)->get();return view('library.inventory-show',compact('inv','total','found','missing'));}
 public function inventoryScan(Request $r,$id){$this->manage($r);$inv=DB::table('library_inventories')->find($id);abort_unless($inv&&$inv->status==='open',422);$d=$r->validate(['code'=>'required|string|max:100']);$c=DB::table('library_copies')->where(fn($q)=>$q->where('barcode',$d['code'])->orWhere('inventory_number',$d['code']))->first();abort_if(!$c,404,'Экземпляр не найден.');DB::table('library_inventory_scans')->updateOrInsert(['library_inventory_id'=>$id,'library_copy_id'=>$c->id],['scanned_by'=>$r->user()->id,'scanned_at'=>now()]);return back();}
 public function inventoryClose(Request $r,$id){$this->manage($r);DB::table('library_inventories')->where(['id'=>$id,'status'=>'open'])->update(['status'=>'closed','closed_on'=>today(),'updated_at'=>now()]);return back();}
 public function coverage(Request $r){$this->manage($r);$rows=DB::table('library_subject_books as l')->join('library_books as b','b.id','=','l.library_book_id')->join('subjects as s','s.id','=','l.subject_id')->leftJoin('study_groups as g','g.id','=','l.study_group_id')->select('l.*','b.title','s.name as subject_name','g.name as group_name')->get();foreach($rows as $x){$x->copies=DB::table('library_copies')->where('library_book_id',$x->library_book_id)->whereNotIn('status',['written_off','lost'])->count();$x->students=$x->study_group_id?DB::table('students')->where(['current_group_id'=>$x->study_group_id,'status'=>'active'])->count():null;$x->deficit=max(0,(int)($x->recommended_copies?:$x->students?:0)-$x->copies);}return view('library.coverage',compact('rows'));}
}